// Analyze error and determine retry strategy
const error = $input.first().json.error;
const execution = $input.first().json.execution;

const errorMessage = error.message || 'Unknown error';
const workflowName = execution.workflowData?.name || 'Unknown workflow';
const executionId = execution.id;

// Categorize error type
let errorCategory = 'unknown';
let shouldRetry = false;
let retryDelay = 0;

// Network errors - retry with backoff
if (errorMessage.includes('ECONNREFUSED') || 
    errorMessage.includes('ETIMEDOUT') || 
    errorMessage.includes('timeout') ||
    errorMessage.includes('socket hang up')) {
  errorCategory = 'network';
  shouldRetry = true;
  retryDelay = 30; // 30 seconds
}

// Rate limiting - retry with longer delay
if (errorMessage.includes('429') || 
    errorMessage.includes('rate limit') ||
    errorMessage.includes('Too Many Requests')) {
  errorCategory = 'rate_limit';
  shouldRetry = true;
  retryDelay = 300; // 5 minutes
}

// API authentication errors - don't retry
if (errorMessage.includes('401') || 
    errorMessage.includes('403') ||
    errorMessage.includes('Unauthorized') ||
    errorMessage.includes('Forbidden')) {
  errorCategory = 'auth';
  shouldRetry = false;
}

// Data validation errors - don't retry
if (errorMessage.includes('required') || 
    errorMessage.includes('validation') ||
    errorMessage.includes('invalid')) {
  errorCategory = 'validation';
  shouldRetry = false;
}

// Server errors - retry once
if (errorMessage.includes('500') || 
    errorMessage.includes('502') ||
    errorMessage.includes('503')) {
  errorCategory = 'server_error';
  shouldRetry = true;
  retryDelay = 60; // 1 minute
}

return [{
  json: {
    error_message: errorMessage,
    error_category: errorCategory,
    workflow_name: workflowName,
    execution_id: executionId,
    should_retry: shouldRetry,
    retry_delay_seconds: retryDelay,
    timestamp: new Date().toISOString(),
    error_stack: error.stack?.substring(0, 500) || ''
  }
}];

